"""
Heti delegacio riport generator.

Ez a modul a shared_delegations adataibol heti riportot keszit:
- Feladatok szama allapot szerint
- Atlagos vegrehajtasi ido
- Delegalt es befejezett feladatok statisztikaja

Futtatas:
    python3 core/delegation_report.py
    python3 core/delegation_report.py --week 2025-W01
    python3 core/delegation_report.py --output report.json
"""

import argparse
import json
import os
import sys
from collections import defaultdict, Counter
from datetime import datetime, timedelta
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple


# ---------------------------------------------------------------------------
# Konstansok
# ---------------------------------------------------------------------------

REPO_ROOT = Path(__file__).resolve().parent.parent
DATA_DIR = REPO_ROOT / "data"
SHARED_DELEGATIONS_JSON = DATA_DIR / "shared_delegations.json"
SHARED_DELEGATIONS_PY = REPO_ROOT / "shared_delegations.py"
CORE_DIR = REPO_ROOT / "core"

# Allapotok, amiket a riport kovet
KNOWN_STATUSES = [
    "pending",
    "in_progress",
    "completed",
    "failed",
    "cancelled",
    "timeout",
]

# Magyar cimkek a riporthoz
STATUS_LABELS_HU = {
    "pending": "Fuggoben",
    "in_progress": "Folyamatban",
    "completed": "Befejezett",
    "failed": "Sikertelen",
    "cancelled": "Megszakitva",
    "timeout": "Idotullpes",
}


# ---------------------------------------------------------------------------
# Adatbetoltes
# ---------------------------------------------------------------------------

def _load_from_json(path: Path) -> List[Dict[str, Any]]:
    """Betolti a delegaciokat egy JSON fajlbol."""
    if not path.exists():
        return []
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        # Lehet, hogy egy wrapper dictben van
        for key in ("delegations", "tasks", "items", "data"):
            if key in data and isinstance(data[key], list):
                return data[key]
        return [data]
    return []


def _load_from_module() -> List[Dict[str, Any]]:
    """Probalja importalni a shared_delegations modult."""
    if REPO_ROOT not in sys.path:
        sys.path.insert(0, str(REPO_ROOT))
    if CORE_DIR not in sys.path:
        sys.path.insert(0, str(CORE_DIR))
    try:
        import shared_delegations  # type: ignore
        if hasattr(shared_delegations, "get_delegations"):
            return shared_delegations.get_delegations()
        if hasattr(shared_delegations, "DELEGATIONS"):
            d = shared_delegations.DELEGATIONS
            return d if isinstance(d, list) else [d]
        if hasattr(shared_delegations, "shared_delegations"):
            d = shared_delegations.shared_delegations
            return d if isinstance(d, list) else [d]
    except Exception:
        pass
    return []


def load_delegations() -> List[Dict[str, Any]]:
    """
    Betolti a shared_delegations adatait tobb forrasbol.
    Sorrend: JSON fajl -> Python modul -> ures lista.
    """
    delegations = _load_from_json(SHARED_DELEGATIONS_JSON)
    if delegations:
        return delegations
    delegations = _load_from_module()
    if delegations:
        return delegations
    return []


# ---------------------------------------------------------------------------
# Segedfuggvenyek
# ---------------------------------------------------------------------------

def _parse_datetime(value: Any) -> Optional[datetime]:
    """Biztonsagos datetime parse."""
    if value is None:
        return None
    if isinstance(value, datetime):
        return value
    if isinstance(value, str):
        formats = [
            "%Y-%m-%dT%H:%M:%S",
            "%Y-%m-%dT%H:%M:%S.%f",
            "%Y-%m-%dT%H:%M:%SZ",
            "%Y-%m-%dT%H:%M:%S.%fZ",
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
            "%Y-%m-%dT%H:%M:%S%z",
            "%Y-%m-%dT%H:%M:%S.%f%z",
        ]
        for fmt in formats:
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                continue
        try:
            return datetime.fromisoformat(value.replace("Z", "+00:00"))
        except Exception:
            return None
    return None


def _get_week_key(dt: datetime) -> str:
    """ISO het azonosito (pl. 2025-W03)."""
    iso = dt.isocalendar()
    return f"{iso[0]}-W{iso[1]:02d}"


def _get_current_week_key() -> str:
    """Az aktualis het azonositoja."""
    return _get_week_key(datetime.now())


def _get_field(delegation: Dict[str, Any], *names: str, default: Any = None) -> Any:
    """Tobb lehetséges mezonev probalasa."""
    for name in names:
        if name in delegation and delegation[name] is not None:
            return delegation[name]
    return default


def _compute_duration(delegation: Dict[str, Any]) -> Optional[float]:
    """
    Kiszamitja a vegrehajtasi idot masodpercben, ha lehet.
    """
    start = _parse_datetime(
        _get_field(delegation, "started_at", "start_time", "created_at", "delegated_at")
    )
    end = _parse_datetime(
        _get_field(delegation, "completed_at", "end_time", "finished_at", "resolved_at")
    )
    if start and end:
        delta = (end - start).total_seconds()
        return delta if delta >= 0 else None
    # Ha van kozvetlen duration mező
    duration = _get_field(delegation, "duration_seconds", "duration", "execution_time")
    if duration is not None:
        try:
            return float(duration)
        except (TypeError, ValueError):
            return None
    return None


def _get_status(delegation: Dict[str, Any]) -> str:
    """Kinyeri az allapotot."""
    status = _get_field(delegation, "status", "state", "result", default="unknown")
    if isinstance(status, dict):
        status = status.get("status", status.get("state", "unknown"))
    return str(status).lower().strip() if status else "unknown"


def _get_timestamp(delegation: Dict[str, Any]) -> Optional[datetime]:
    """Kinyeri a fo idobelyeget a heti csoportosítashoz."""
    for field in ("created_at", "delegated_at", "started_at", "timestamp", "date", "submitted_at"):
        dt = _parse_datetime(_get_field(delegation, field))
        if dt:
            return dt
    return None


# ---------------------------------------------------------------------------
# Riport generalas
# ---------------------------------------------------------------------------

def generate_weekly_report(
    delegations: List[Dict[str, Any]],
    week_key: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Heti delegacio riportot general.

    Args:
        delegations: A delegaciok listaja.
        week_key: ISO het azonosito (pl. '2025-W03'). Ha None, az aktualis hetet hasznalja.

    Returns:
        Riport dict.
    """
    if week_key is None:
        week_key = _get_current_week_key()

    # Szures az adott hetre
    weekly_delegations: List[Dict[str, Any]] = []
    ungrouped = 0

    for delegation in delegations:
        dt = _get_timestamp(delegation)
        if dt is None:
            ungrouped += 1
            continue
        if _get_week_key(dt) == week_key:
            weekly_delegations.append(delegation)

    # Statisztika szamitas
    status_counts: Counter = Counter()
    durations: List[float] = []
    agent_stats: Dict[str, Dict[str, Any]] = defaultdict(
        lambda: {"total": 0, "completed": 0, "failed": 0, "durations": []}
    )
    total_duration = 0.0
    completed_count = 0

    for delegation in weekly_delegations:
        status = _get_status(delegation)
        status_counts[status] += 1

        duration = _compute_duration(delegation)
        if duration is not None:
            durations.append(duration)
            total_duration += duration

        if status == "completed":
            completed_count += 1

        # Agent szintu statisztika
        agent = _get_field(
            delegation,
            "delegate_to",
            "agent",
            "target_agent",
            "assigned_to",
            default="unknown",
        )
        if isinstance(agent, dict):
            agent = agent.get("id", agent.get("name", "unknown"))
        agent = str(agent)

        agent_stats[agent]["total"] += 1
        if status == "completed":
            agent_stats[agent]["completed"] += 1
            if duration is not None:
                agent_stats[agent]["durations"].append(duration)
        elif status == "failed":
            agent_stats[agent]["failed"] += 1

    # Atlagos vegrehajtasi ido (csak befejezett feladatoknal)
    avg_duration = (total_duration / len(durations)) if durations else 0.0
    avg_duration_completed = (
        sum(d for d, deleg in zip(durations, weekly_delegations)
            if _get_status(deleg) == "completed")
        / max(completed_count, 1)
    ) if completed_count > 0 and durations else 0.0

    # Agent statisztika rendese
    agent_summary = {}
    for agent, stats in sorted(agent_stats.items()):
        avg_agent = sum(stats["durations"]) / len(stats["durations"]) if stats["durations"] else 0.0
        agent_summary[agent] = {
            "total_tasks": stats["total"],
            "completed": stats["completed"],
            "failed": stats["failed"],
            "success_rate": round(stats["completed"] / stats["total"] * 100, 2) if stats["total"] else 0.0,
            "avg_duration_seconds": round(avg_agent, 2),
        }

    # Osszes allapot (ismert + egyeb)
    all_statuses = {}
    for status in KNOWN_STATUSES:
        if status_counts.get(status, 0) > 0:
            all_statuses[status] = status_counts[status]
    for status, count in sorted(status_counts.items()):
        if status not in KNOWN_STATUSES:
            all_statuses[status] = count

    total_tasks = len(weekly_delegations)
    success_rate = (completed_count / total_tasks * 100) if total_tasks > 0 else 0.0

    report = {
        "report_type": "weekly_delegation_report",
        "week": week_key,
        "generated_at": datetime.now().isoformat(),
        "summary": {
            "total_tasks": total_tasks,
            "completed": completed_count,
            "success_rate_percent": round(success_rate, 2),
            "avg_duration_seconds": round(avg_duration, 2),
            "avg_duration_completed_seconds": round(avg_duration_completed, 2),
            "tasks_with_duration_data": len(durations),
            "ungrouped_tasks": ungrouped,
        },
        "status_breakdown": dict(all_statuses),
        "status_breakdown_hu": {
            STATUS_LABELS_HU.get(k, k): v for k, v in all_statuses.items()
        },
        "agent_performance": agent_summary,
    }

    return report


def list_available_weeks(delegations: List[Dict[str, Any]]) -> List[str]:
    """Visszaadja az elerheto hetek listajat (csokkenő sorrendben)."""
    weeks = set()
    for delegation in delegations:
        dt = _get_timestamp(delegation)
        if dt:
            weeks.add(_get_week_key(dt))
    return sorted(weeks, reverse=True)


# ---------------------------------------------------------------------------
# Riport formatumas / kiiras
# ---------------------------------------------------------------------------

def format_duration(seconds: float) -> str:
    """Masodperc -> olvashato idotartam."""
    if seconds <= 0:
        return "N/A"
    if seconds < 60:
        return f"{seconds:.1f}s"
    if seconds < 3600:
        return f"{seconds / 60:.1f}p"
    return f"{seconds / 3600:.2f}ó" if seconds < 86400 else f"{seconds / 3600:.1f}ó"


def print_report(report: Dict[str, Any]) -> None:
    """Szepen formatumozott riport a konzolra."""
    print("=" * 70)
    print(f"  HETI DELEGACIO RIPORT — {report['week']}")
    print("=" * 70)
    print(f"  Generalva: {report['generated_at']}")
    print()

    summary = report["summary"]
    print("  --- OSSZEGZO ---")
    print(f"  Osszes feladat:          {summary['total_tasks']}")
    print(f"  Befejezett:              {summary['completed']}")
    print(f"  Sikeresseg arany:        {summary['success_rate_percent']}%")
    print(f"  Atlagos vegrehajtasi ido:{summary['avg_duration_seconds']}s")
    print(f"  (csak befejezettek):     {summary['avg_duration_completed_seconds']}s")
    print(f"  Idoadasu feladatok:      {summary['tasks_with_duration_data']}")
    if summary["ungrouped_tasks"] > 0:
        print(f"  (Idobelyeg nelkul:       {summary['ungrouped_tasks']})")
    print()

    print("  --- ALLOT SZERINT ---")
    if report["status_breakdown_hu"]:
        for status, count in report["status_breakdown_hu"].items():
            bar = "█" * min(count, 40)
            print(f"  {status:<20} {count:>5}  {bar}")
    else:
        print("  (Nincs adat)")
    print()

    print("  --- AGENT TELEJTESMENY ---")
    if report["agent_performance"]:
        print(f"  {'Agent':<25} {'Osszes':>7} {'Kesz':>6} {'Hiba':>6} {'Sik%':>7} {'AtlagIdo':>10}")
        print(f"  {'-'*25} {'-'*7} {'-'*6} {'-'*6} {'-'*7} {'-'*10}")
        for agent, stats in report["agent_performance"].items():
            print(
                f"  {agent:<25} {stats['total_tasks']:>7} "
                f"{stats['completed']:>6} {stats['failed']:>6} "
                f"{stats['success_rate']:>6.1f}% {stats['avg_duration_seconds']:>9.1f}s"
            )
    else:
        print("  (Nincs agent adat)")
    print()
    print("=" * 70)


def save_report(report: Dict[str, Any], output_path: str) -> None:
    """Riport mentese JSON fajlba."""
    path = Path(output_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(report, f, indent=2, ensure_ascii=False)
    print(f"  Riport mentve: {path}")


# ---------------------------------------------------------------------------
# Demo adatok (ha nincs valodi adat)
# ---------------------------------------------------------------------------

def _generate_demo_delegations() -> List[Dict[str, Any]]:
    """Demo delegaciok a teszthez, ha nincs valodi adat."""
    now = datetime.now()
    week_key = _get_week_key(now)
    # Hetfo datuma
    monday = now - timedelta(days=now.weekday())

    demos = []
    statuses = ["completed", "completed", "completed", "failed", "in_progress",
                "pending", "completed", "timeout", "cancelled", "completed"]
    agents = ["agent_alpha", "agent_beta", "agent_gamma", "agent_delta"]

    for i, status in enumerate(statuses):
        created = monday + timedelta(hours=i * 5, minutes=23)
        duration = None
        if status in ("completed", "failed", "timeout"):
            duration_secs = [45.2, 120.5, 33.1, 300.0, 12.7, 88.3, 210.4, 15.0][i % 8]
            completed_time = created + timedelta(seconds=duration_secs)
            duration = duration_secs
        else:
            completed_time = None

        entry = {
            "id": f"deleg_{week_key}_{i:03d}",
            "task": f"Demo feladat #{i+1}",
            "delegate_to": agents[i % len(agents)],
            "status": status,
            "created_at": created.isoformat(),
            "started_at": created.isoformat(),
        }
        if completed_time:
            entry["completed_at"] = completed_time.isoformat()
            entry["duration_seconds"] = duration
        demos.append(entry)

    return demos


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def main() -> int:
    parser = argparse.ArgumentParser(
        description="Heti delegacio riport generator (A2A Mesh)"
    )
    parser.add_argument(
        "--week",
        type=str,
        default=None,
        help="ISO het azonosito, pl. 2025-W03. Alapertelmezett: aktualis het.",
    )
    parser.add_argument(
        "--output",
        "-o",
        type=str,
        default=None,
        help="JSON kimeneti fajl utvonala (pl. reports/week.json).",
    )
    parser.add_argument(
        "--list-weeks",
        action="store_true",
        help="Listazza az elerheto heteket es kilep.",
    )
    parser.add_argument(
        "--demo",
        action="store_true",
        help="Demo adatokkal futtas (ha nincs valodi adat).",
    )
    args = parser.parse_args()

    # Adat betoltese
    delegations = load_delegations()

    if not delegations:
        print("  [INFO] Nincs elerheto shared_delegations adat.")
        print("  [INFO] Demo adatokkal futtatas...")
        print()
        delegations = _generate_demo_delegations()
    elif args.demo:
        delegations = _generate_demo_delegations()

    # Hetek listazasa
    if args.list_weeks:
        weeks = list_available_weeks(delegations)
        if weeks:
            print("  Elerheto hetek:")
            for w in weeks:
                marker = " (aktualis)" if w == _get_current_week_key() else ""
                print(f"    {w}{marker}")
        else:
            print("  Nincs elerheto het az adatokban.")
        return 0

    # Het meghatarozasa
    week_key = args.week if args.week else _get_current_week_key()

    # Riport generalasa
    report = generate_weekly_report(delegations, week_key=week_key)

    # Riport kiirasa
    print_report(report)

    # Riport mentese ha kerve volt
    if args.output:
        save_report(report, args.output)

    # Ha nincs egyetlen feladat sem a hetben, figyelmeztetes
    if report["summary"]["total_tasks"] == 0:
        print(f"  [FIGYELMEZTETES] Nincs feladat a {week_key} hetben.")
        print("  Elerheto hetek:")
        weeks = list_available_weeks(delegations)
        for w in weeks[:10]:
            print(f"    {w}")
        if len(weeks) > 10:
            print(f"    ... es meg {len(weeks) - 10} het")
        print()

    return 0


if __name__ == "__main__":
    sys.exit(main())